import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('la-salvacion', 'A',
 [dict(t=653, e=705, titulo='El Señor salvó espíritu, alma y cuerpo', txt='Quiere decir que cuando usted aceptó al Señor, ya lo adoptaron para que usted sea hijo de Dios. Pero dice también que estamos aguardando ansiosamente la adopción como hijos y la redención de nuestro cuerpo. Entonces, quiere decir que el Señor salvó nuestro espíritu, salvó nuestra alma y salvó nuestro cuerpo; que va a haber una transformación definitivamente, porque carne y sangre no heredarán el reino de Dios. Miremos otra cosa: ¿de qué nos ha salvado? De la enfermedad. Entonces, ¿por qué me enfermo? Porque debemos tomar al Señor en cuenta, de que él nos quiere sanar esta mañana, hermano.'),
  dict(t=1964, e=2007, titulo='El Jesús que resucitó y viene por nosotros', txt='Cuando usted tiene comunión con un Jesús histórico, con un Jesús que vivió aquí en la tierra, pero no ha tenido comunión con el que resucitó, con el que tomó nuevamente su gloria y está sentado a la diestra del Padre esperando venir por usted y por mí… ¿Cuántos están esperando al Señor Jesucristo? ¿Cuántos pueden creer que hoy podría entrar el Señor por usted y por mí? Así que ayúdanos, Señor, a cambiar, porque si no, solo lo vamos a ver pasar y nos quedamos.'),
  dict(t=3927, e=3976, titulo='Salvos de esta generación perversa', txt='Pero si llegamos en hogar a Dios, hermano, Dios guarda de la generación perversa. ¿De qué te va a salvar el Señor? De la generación perversa: «Y con muchas otras palabras testificaba y les exhortaba diciendo: Sed salvos de esta perversa generación». Ahora, él estaba hablando en aquel tiempo, pero esa palabra, esa voz es para este tiempo. ¿Y qué nos está diciendo? Sean salvos de esta generación que están viviendo, que es una generación perversa.')],
 [dict(t=1310, txt='En el nombre de Jesús vengo desatando las obras buenas que Dios ya escribió antes de la fundación del mundo para que tú puedas caminar en ellas.'),
  dict(t=2643, txt='Con temor preparó un arca para la salvación de su casa. Esa arca está abierta.'),
  dict(t=4006, txt='Nosotros pecamos, nos alcanza el pecado, pero dice el Señor que él nos va a salvar de todo pecado.')],
 ['¿En cuál de las tres áreas —espíritu, alma o cuerpo— necesitas hoy que el Señor te salve y te sane?',
  '¿Conoces solo al Jesús que vivió en la tierra, o también tienes comunión con el que resucitó y viene por ti?',
  '¿De qué parte de esta generación necesitas ser salvo, y a quién de tu casa quieres invitar a entrar al arca?'])
